mapper.update:
UPDATE member
SET member_delete_yn = #{newStatus}
WHERE member_id = #{member_id};

mapper.select:
SELECT COUNT(*)
FROM member
WHERE member_delete_yn = 0;

SELECT m.*,
       (
           SELECT COUNT(*)
           FROM follow f
           WHERE f.followed_member_id = m.member_id
       ) AS followerNum
FROM member m
WHERE m.member_id = #{member_id}
  AND m.member_delete_yn = 0;
